using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IAsyncDisposable
{
    private readonly HttpListener listener = new();
    private readonly Uri baseAddress;
    private readonly HttpClient client;
    private string? method, path, contentType, body;

    public HttpPaymentGatewayTests()
    {
        var probe = new TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();

        baseAddress = new Uri($"http://127.0.0.1:{port}/");
        listener.Prefixes.Add(baseAddress.ToString());
        listener.Start();
        client = new HttpClient { BaseAddress = baseAddress };
    }

    private Task<AuthorizationOutcome> Authorize(int status, string responseBody, Money? amount = null)
    {
        var served = Serve(status, responseBody);
        return Task.Run(async () =>
        {
            var outcome = await new HttpPaymentGateway(client)
                .AuthorizeAsync("ORD-7", amount ?? new Money(12.50m, "eur"), CancellationToken.None);
            await served;
            return outcome;
        });
    }

    private async Task Serve(int status, string responseBody)
    {
        var context = await listener.GetContextAsync();
        var request = context.Request;
        method = request.HttpMethod;
        path = request.Url!.AbsolutePath;
        contentType = request.ContentType;
        using (var reader = new StreamReader(request.InputStream, Encoding.UTF8)) body = await reader.ReadToEndAsync();

        var bytes = Encoding.UTF8.GetBytes(responseBody);
        context.Response.StatusCode = status;
        context.Response.ContentType = "application/json";
        await context.Response.OutputStream.WriteAsync(bytes);
        context.Response.Close();
    }

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        await Authorize(200, """{"status":"approved"}""");

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
        using var json = JsonDocument.Parse(body!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize(200, """{"status":"approved"}"""));
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(200, """{"status":"declined"}"""));
    }

    [Fact]
    public async Task Unknown_extra_fields_in_the_answer_are_ignored()
    {
        Assert.Equal(AuthorizationOutcome.Approved,
            await Authorize(200, """{"id":"abc","status":"approved","risk":{"score":3}}"""));
    }

    [Fact]
    public async Task A_refusal_with_402_is_a_declined_outcome()
    {
        Assert.Equal(AuthorizationOutcome.Declined,
            await Authorize(402, """{"error":"card_refused"}"""));
    }

    [Fact]
    public async Task An_answer_without_a_status_is_not_treated_as_approved()
    {
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(200, """{"result":"approved"}"""));
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_are_raised_instead_of_being_taken_for_a_decision(int status)
    {
        await Assert.ThrowsAsync<HttpRequestException>(() => Authorize(status, """{"status":"approved"}"""));
    }

    [Fact]
    public async Task A_body_that_is_not_json_is_raised()
    {
        await Assert.ThrowsAsync<JsonException>(() => Authorize(200, "<html>oops</html>"));
    }

    public async ValueTask DisposeAsync()
    {
        client.Dispose();
        listener.Close();
        await Task.CompletedTask;
    }
}
